        22 => self.build(&.{ .{ .tag = .@"set" }, .{ .tag = .@"%=" }, pass[0], .nil, pass[2] }, .tree),
        23 => self.build(&.{ .{ .tag = .@"set" }, .{ .tag = .@"&=" }, pass[0], .nil, pass[2] }, .tree),
